//! Plugin reports (M25, T90): report types generated by a plugin handler as
//! a limited job, export formats rendered by a plugin, annotations on Puppet
//! run reports, datasets for the custom report builder and other plugins,
//! and the `report.received` watcher. Results are structured sections the
//! host renders, never HTML. See docs/architecture/PLUGIN_PLATFORM.md §17.7.

use std::collections::{BTreeMap, HashMap};
use std::sync::{Arc, Mutex};

use base64::Engine;
use chrono::{DateTime, Utc};
use serde::Deserialize;
use serde_json::{json, Map, Value};
use uuid::Uuid;

use super::events::EventBus;
use super::filter::pattern_matches;
use super::invoke::{invoke_with_timeout, HandlerKind, PluginHooks};
use super::manager::PluginManager;
use crate::config::PluginReportsConfig;
use crate::db::PluginReportsRepository;
use crate::models::*;
use crate::services::puppetdb::{PuppetDbClient, QueryBuilder, QueryParams};

const MAX_SECTIONS: usize = 50;
const MAX_TEXT_CHARS: usize = 100_000;
const MAX_PARAMS_BYTES: usize = 64 * 1024;
const MAX_VALUE_BYTES: usize = 16 * 1024;
const MAX_ROWS_PER_CALL: usize = 5_000;
const MAX_QUERY_LIMIT: u32 = 1_000;
const WATCH_BATCH: u32 = 500;

#[derive(Debug, thiserror::Error)]
pub enum ReportError {
    #[error("{0}")]
    NotFound(String),
    #[error("{0}")]
    Invalid(String),
    #[error("{0}")]
    Forbidden(String),
    /// The plugin failed, timed out or its runtime is unavailable.
    #[error("{0}")]
    Failed(String),
}

/// Rows a running report job delivered in chunks (`reports.emit_rows`).
struct JobBuffer {
    plugin_id: String,
    sections: BTreeMap<String, Vec<Map<String, Value>>>,
    rows: u64,
}

/// In-memory state of plugin report jobs.
pub struct ReportsRuntime {
    cfg: PluginReportsConfig,
    jobs: Mutex<HashMap<String, JobBuffer>>,
}

impl ReportsRuntime {
    pub fn new(cfg: PluginReportsConfig) -> Self {
        Self {
            cfg,
            jobs: Mutex::new(HashMap::new()),
        }
    }

    pub fn config(&self) -> &PluginReportsConfig {
        &self.cfg
    }

    fn max_rows(&self) -> u64 {
        self.cfg.max_rows.max(1)
    }

    fn open(&self, job_id: &str, plugin_id: &str) {
        self.jobs.lock().unwrap_or_else(|e| e.into_inner()).insert(
            job_id.to_string(),
            JobBuffer {
                plugin_id: plugin_id.to_string(),
                sections: BTreeMap::new(),
                rows: 0,
            },
        );
    }

    fn close(&self, job_id: &str) -> Option<JobBuffer> {
        self.jobs
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .remove(job_id)
    }

    /// `reports.emit_rows`: appends rows to a table section of a running
    /// job of the same plugin, within the row limit.
    pub fn emit_rows(
        &self,
        plugin_id: &str,
        job_id: &str,
        section: &str,
        rows: Vec<Value>,
    ) -> Result<u64, ReportError> {
        if !valid_section_id(section) {
            return Err(ReportError::Invalid(format!(
                "section id '{}' is invalid",
                section
            )));
        }
        if rows.len() > MAX_ROWS_PER_CALL {
            return Err(ReportError::Invalid(format!(
                "at most {} rows per call",
                MAX_ROWS_PER_CALL
            )));
        }
        let mut parsed = Vec::with_capacity(rows.len());
        for r in rows {
            match r {
                Value::Object(m) => parsed.push(m),
                _ => return Err(ReportError::Invalid("rows must be objects".into())),
            }
        }
        let max = self.max_rows();
        let mut jobs = self.jobs.lock().unwrap_or_else(|e| e.into_inner());
        let job = jobs
            .get_mut(job_id)
            .filter(|j| j.plugin_id == plugin_id)
            .ok_or_else(|| ReportError::NotFound("no running report job with that id".into()))?;
        if job.rows + parsed.len() as u64 > max {
            return Err(ReportError::Invalid(format!(
                "the report row limit ({}) is reached",
                max
            )));
        }
        job.rows += parsed.len() as u64;
        job.sections
            .entry(section.to_string())
            .or_default()
            .extend(parsed);
        Ok(job.rows)
    }
}

struct JobGuard<'a> {
    rt: &'a ReportsRuntime,
    id: &'a str,
}

impl Drop for JobGuard<'_> {
    fn drop(&mut self) {
        self.rt.close(self.id);
    }
}

fn valid_section_id(s: &str) -> bool {
    !s.is_empty()
        && s.len() <= 64
        && s.bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'-' || b == b'_')
}

/// Text shown by the host: no control characters except newline and tab.
fn plain_text(s: &str, max: usize) -> String {
    s.chars()
        .filter(|c| !c.is_control() || *c == '\n' || *c == '\t')
        .take(max)
        .collect()
}

fn opt_text(s: Option<String>, max: usize) -> Option<String> {
    s.map(|t| plain_text(&t, max)).filter(|t| !t.is_empty())
}

/// A valid PuppetDB report hash: 40 to 64 lowercase hexadecimal characters.
pub fn valid_report_hash(h: &str) -> bool {
    (40..=64).contains(&h.len())
        && h.bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
}

fn plain_json(v: &Value) -> bool {
    match v {
        Value::String(s) => !s.chars().any(char::is_control),
        Value::Array(a) => a.iter().all(plain_json),
        Value::Object(o) => o
            .iter()
            .all(|(k, x)| !k.chars().any(char::is_control) && plain_json(x)),
        _ => true,
    }
}

// ============================================================================
// Parameters (JSON Schema subset)
// ============================================================================

/// Validates report parameters against the schema subset accepted by the
/// manifest: object properties of type string, integer, number, boolean or
/// array, with `required`, `enum`, `minimum`, `maximum`, `maxLength` and the
/// `date` / `date-time` formats. Unknown parameters are refused.
pub fn validate_params(schema: Option<&Value>, params: &Value) -> Result<(), Vec<String>> {
    let mut p = Vec::new();
    let obj = match params {
        Value::Null => return check_required(schema, &Map::new()),
        Value::Object(o) => o,
        _ => return Err(vec!["parameters must be an object".to_string()]),
    };
    if serde_json::to_vec(params)
        .map(|b| b.len())
        .unwrap_or(usize::MAX)
        > MAX_PARAMS_BYTES
    {
        return Err(vec!["parameters are larger than 64 KB".to_string()]);
    }
    let props = schema
        .and_then(|s| s.get("properties"))
        .and_then(Value::as_object);
    for (name, v) in obj {
        let Some(prop) = props.and_then(|p| p.get(name)) else {
            p.push(format!("unknown parameter '{}'", name));
            continue;
        };
        if v.is_null() {
            continue;
        }
        let t = prop.get("type").and_then(Value::as_str).unwrap_or("");
        let type_ok = match t {
            "string" => v.is_string(),
            "integer" => v.is_i64() || v.is_u64(),
            "number" => v.is_number(),
            "boolean" => v.is_boolean(),
            "array" => v.is_array(),
            _ => false,
        };
        if !type_ok {
            p.push(format!("parameter '{}' must be of type {}", name, t));
            continue;
        }
        if !plain_json(v) {
            p.push(format!("parameter '{}' contains control characters", name));
        }
        if let Some(values) = prop.get("enum").and_then(Value::as_array) {
            if !values.contains(v) {
                p.push(format!(
                    "parameter '{}' is not one of the allowed values",
                    name
                ));
            }
        }
        if let Some(n) = v.as_f64() {
            if prop
                .get("minimum")
                .and_then(Value::as_f64)
                .is_some_and(|m| n < m)
            {
                p.push(format!("parameter '{}' is below its minimum", name));
            }
            if prop
                .get("maximum")
                .and_then(Value::as_f64)
                .is_some_and(|m| n > m)
            {
                p.push(format!("parameter '{}' is above its maximum", name));
            }
        }
        if let Some(s) = v.as_str() {
            let max = prop
                .get("maxLength")
                .and_then(Value::as_u64)
                .unwrap_or(1000) as usize;
            if s.chars().count() > max {
                p.push(format!("parameter '{}' is longer than {}", name, max));
            }
            match prop.get("format").and_then(Value::as_str) {
                Some("date") if chrono::NaiveDate::parse_from_str(s, "%Y-%m-%d").is_err() => {
                    p.push(format!("parameter '{}' must be a date (YYYY-MM-DD)", name))
                }
                Some("date-time") if DateTime::parse_from_rfc3339(s).is_err() => p.push(format!(
                    "parameter '{}' must be an RFC 3339 date and time",
                    name
                )),
                _ => {}
            }
        }
    }
    if let Err(mut e) = check_required(schema, obj) {
        p.append(&mut e);
    }
    if p.is_empty() {
        Ok(())
    } else {
        Err(p)
    }
}

fn check_required(schema: Option<&Value>, obj: &Map<String, Value>) -> Result<(), Vec<String>> {
    let missing: Vec<String> = schema
        .and_then(|s| s.get("required"))
        .and_then(Value::as_array)
        .map(|req| {
            req.iter()
                .filter_map(Value::as_str)
                .filter(|r| obj.get(*r).is_none_or(Value::is_null))
                .map(|r| format!("parameter '{}' is required", r))
                .collect()
        })
        .unwrap_or_default();
    if missing.is_empty() {
        Ok(())
    } else {
        Err(missing)
    }
}

